-- 0067 — Dix-neuvième lot de recettes du catalogue (publiées et validées) :
-- plats asiatiques et recettes rapides aux tomates séchées, au moins 20 g de protéines par part (calcul Ciqual).
-- Fichier GÉNÉRÉ par scripts/generate-recipes-lot19.py depuis scripts/data/recipes-lot19.py.
-- Recettes originales (D7). Ne jamais éditer une fois appliqué.
-- 15 recettes, 140 lignes d'ingrédients, 75 étapes.

insert into public.recipes (slug, title, description, storage_note, servings, prep_minutes,
  cook_minutes, tags, status, source, source_ref, validated_at)
select v.slug, v.title, v.description, v.storage, v.servings, v.prep, v.cook, v.tags,
  'published', 'curated', 'Aux Petits Oignons — recette originale', now()
from (values
  ('curry-rouge-poulet-butternut-coco', 'Curry rouge de poulet, butternut et lait de coco', 'Un curry thaï doux au lait de coco, avec du poulet émincé et des cubes de butternut fondants, servi avec du riz thaï et du citron vert.', 'Se garde 3 jours au réfrigérateur ; le curry est encore meilleur le lendemain.', 2, 15, 25, array['plat', 'mijote', 'monde']::text[]),
  ('tofu-curry-rouge-epinards-coco', 'Tofu au curry rouge, épinards et lait de coco', 'Des cubes de tofu dorés mijotés dans un curry rouge au lait de coco, avec des épinards fondus et du riz jasmin. Un bloc entier pour deux.', 'Se garde 3 jours au réfrigérateur ; réchauffer doucement à la poêle.', 2, 10, 20, array['plat', 'poele', 'monde', 'lunch-box']::text[]),
  ('poulet-satay-cacahuete-carottes-riz', 'Poulet sauce satay à la cacahuète, carottes et riz', 'Du poulet sauté nappé d''une sauce crémeuse au beurre de cacahuète, lait de coco, sauce soja et citron vert, avec des carottes et du riz jasmin.', 'Se garde 3 jours au réfrigérateur ; détendre la sauce d''un peu d''eau en réchauffant.', 2, 10, 20, array['plat', 'poele', 'monde']::text[]),
  ('riz-saute-cantonais-oeufs-jambon', 'Riz sauté cantonais aux œufs et au jambon', 'Un riz sauté à la poêle avec des œufs brouillés, des dés de jambon, des carottes et de l''oignon, relevé de sauce soja et d''huile de sésame. Idéal avec un reste de riz.', 'Se garde 2 jours au réfrigérateur ; réchauffer à la poêle bien chaude.', 2, 10, 15, array['plat', 'poele', 'monde', 'anti-gaspi']::text[]),
  ('soupe-nouilles-poulet-gingembre-soja', 'Soupe de nouilles au poulet, gingembre et sauce soja', 'Un bouillon de volaille parfumé au gingembre et à la sauce soja, avec des nouilles de riz, du poulet poché, des champignons, du chou et un œuf mollet.', 'Le bouillon se garde 3 jours au réfrigérateur ; cuire les nouilles au moment de réchauffer.', 2, 15, 20, array['soupe', 'plat', 'monde']::text[]),
  ('boeuf-saute-gingembre-brocoli-riz', 'Bœuf sauté au gingembre et brocoli', 'Des lanières de bœuf saisies au wok avec du brocoli, de l''ail et du gingembre, dans une sauce soja légèrement sucrée au miel, servies avec du riz.', 'Se garde 2 jours au réfrigérateur ; réchauffer rapidement à la poêle pour ne pas durcir le bœuf.', 2, 15, 15, array['plat', 'poele', 'monde']::text[]),
  ('crevettes-sautees-ail-gingembre-nouilles', 'Crevettes sautées ail-gingembre et nouilles de riz', 'Des crevettes sautées à l''ail et au gingembre avec des nouilles de riz, des carottes et du chou, liées à la sauce soja et au citron vert. Prêt en 20 minutes.', 'Se garde 1 jour au réfrigérateur ; à manger de préférence tout de suite.', 2, 10, 10, array['plat', 'poele', 'monde']::text[]),
  ('porc-caramel-soja-riz-thai', 'Porc au caramel et sauce soja, riz thaï', 'Des dés de porc mijotés dans un caramel à la sauce soja, à l''ail et à l''oignon, jusqu''à devenir laqués et fondants, avec du riz thaï et des carottes.', 'Se garde 3 jours au réfrigérateur ou 2 mois au congélateur.', 2, 10, 30, array['plat', 'mijote', 'monde']::text[]),
  ('salade-nouilles-poulet-cacahuete-chou-rouge', 'Salade de nouilles au poulet, cacahuète et chou rouge', 'Une salade froide de nouilles de riz, poulet, chou rouge et carottes râpées, avec une sauce au beurre de cacahuète, sauce soja et citron vert. Parfaite en boîte-repas.', 'Se garde 3 jours au réfrigérateur ; mélanger la sauce au moment de servir si possible.', 2, 20, 10, array['salade', 'plat', 'monde', 'lunch-box']::text[]),
  ('croque-vege-tomates-sechees-epinards', 'Croque végé aux tomates séchées et épinards', 'Des croque-monsieur sans jambon, garnis de fromage frais, tomates séchées, pousses d''épinards et emmental, dorés à la poêle et servis avec une salade.', 'À manger tout de suite ; les croques garnis non cuits se gardent 1 jour au réfrigérateur.', 2, 5, 10, array['plat', 'poele', 'express']::text[]),
  ('omelette-tomates-sechees-feta-ciboulette', 'Omelette aux tomates séchées, feta et ciboulette', 'Une omelette baveuse garnie de tomates séchées et de feta émiettée, parfumée à la ciboulette, avec du pain grillé et de la mâche. Prête en 15 minutes.', 'À manger tout de suite ; froide, elle se glisse dans une boîte-repas pour le lendemain.', 2, 5, 10, array['plat', 'poele', 'express']::text[]),
  ('wraps-poulet-tomates-sechees-fromage-frais', 'Wraps au poulet, tomates séchées et fromage frais', 'Des tortillas tartinées de fromage frais, garnies de poulet doré, de tomates séchées et de mâche, roulées bien serrées. Faciles à emporter.', 'Se garde 2 jours au réfrigérateur, emballé ; ajouter la mâche au dernier moment si possible.', 2, 8, 7, array['plat', 'poele', 'express', 'lunch-box']::text[]),
  ('quesadillas-haricots-rouges-tomates-sechees', 'Quesadillas aux haricots rouges, tomates séchées et cheddar', 'Des tortillas dorées à la poêle, fourrées de haricots rouges écrasés, tomates séchées, oignon rouge et cheddar fondant. Prêt en 15 minutes.', 'Se gardent 2 jours au réfrigérateur ; réchauffer à la poêle pour qu''elles restent croustillantes.', 2, 5, 10, array['plat', 'poele', 'express', 'economique']::text[]),
  ('tartines-ricotta-tomates-sechees-jambon-cru', 'Tartines ricotta, tomates séchées et jambon cru', 'De grandes tartines de pain grillé à la ricotta citronnée, garnies de tomates séchées, de jambon cru et de mâche. Un dîner sans vraie cuisson en 10 minutes.', 'À manger tout de suite ; la ricotta citronnée se garde 2 jours au réfrigérateur.', 2, 10, 3, array['plat', 'express']::text[]),
  ('gnocchis-poeles-tomates-sechees-mozzarella', 'Gnocchis poêlés aux tomates séchées et mozzarella', 'Des gnocchis dorés à la poêle, sans cuisson à l''eau, avec des tomates séchées, des épinards, de la mozzarella fondante et du parmesan.', 'Se garde 1 jour au réfrigérateur ; réchauffer à la poêle.', 2, 5, 12, array['plat', 'poele']::text[])
) as v(slug, title, description, storage, servings, prep, cook, tags);

