insert into public.recipe_steps (recipe_id, position, instruction)
select r.id, v.pos, v.instruction
from (values
  ('curry-rouge-poulet-butternut-coco', 1, 'Éplucher la butternut et la couper en cubes, émincer l''oignon et couper le poulet en lanières.'),
  ('curry-rouge-poulet-butternut-coco', 2, 'Cuire le riz dans une casserole d''eau bouillante selon le temps indiqué sur le paquet, puis l''égoutter.'),
  ('curry-rouge-poulet-butternut-coco', 3, 'Faire revenir l''oignon et la pâte de curry 2 minutes dans l''huile, dans une sauteuse à feu moyen, jusqu''à ce que ça embaume.'),
  ('curry-rouge-poulet-butternut-coco', 4, 'Ajouter le poulet et le saisir 3 minutes, puis ajouter la butternut, le lait de coco et un fond d''eau.'),
  ('curry-rouge-poulet-butternut-coco', 5, 'Laisser mijoter 15 minutes à couvert : la courge doit être tendre et le poulet cuit à cœur.'),
  ('curry-rouge-poulet-butternut-coco', 6, 'Ajouter le jus de citron vert et servir avec le riz et la coriandre.'),
  ('tofu-curry-rouge-epinards-coco', 1, 'Cuire le riz dans une casserole d''eau bouillante selon le temps indiqué sur le paquet, puis l''égoutter.'),
  ('tofu-curry-rouge-epinards-coco', 2, 'Égoutter le tofu, l''éponger et le couper en cubes, et hacher l''ail.'),
  ('tofu-curry-rouge-epinards-coco', 3, 'Dorer le tofu 6 minutes dans l''huile, dans une sauteuse à feu moyen-vif, en le retournant : il doit être doré sur toutes les faces.'),
  ('tofu-curry-rouge-epinards-coco', 4, 'Ajouter l''ail et la pâte de curry 1 minute, puis le lait de coco et la sauce soja, et laisser frémir 5 minutes.'),
  ('tofu-curry-rouge-epinards-coco', 5, 'Ajouter les épinards et les laisser tomber 2 minutes, puis servir avec le riz et le jus de citron vert.'),
  ('poulet-satay-cacahuete-carottes-riz', 1, 'Cuire le riz dans une casserole d''eau bouillante selon le temps indiqué sur le paquet, puis l''égoutter.'),
  ('poulet-satay-cacahuete-carottes-riz', 2, 'Couper le poulet en dés, les carottes en fines rondelles et râper le gingembre.'),
  ('poulet-satay-cacahuete-carottes-riz', 3, 'Fouetter le beurre de cacahuète, le lait de coco, la sauce soja, le jus de citron vert et le gingembre jusqu''à obtenir une sauce lisse.'),
  ('poulet-satay-cacahuete-carottes-riz', 4, 'Faire sauter le poulet et les carottes 8 minutes dans l''huile, dans une poêle à feu moyen-vif : le poulet doit être doré et cuit à cœur.'),
  ('poulet-satay-cacahuete-carottes-riz', 5, 'Verser la sauce et laisser épaissir 2 minutes à feu doux, puis servir avec le riz, les cacahuètes concassées et la coriandre.'),
  ('riz-saute-cantonais-oeufs-jambon', 1, 'Cuire le riz dans une casserole d''eau bouillante selon le temps du paquet, l''égoutter et l''étaler pour qu''il refroidisse (ou utiliser un reste de riz froid).'),
  ('riz-saute-cantonais-oeufs-jambon', 2, 'Couper les carottes en petits dés, émincer l''oignon et couper le jambon en dés.'),
  ('riz-saute-cantonais-oeufs-jambon', 3, 'Brouiller les œufs battus 1 minute dans la moitié de l''huile, dans une grande poêle à feu vif, puis les réserver.'),
  ('riz-saute-cantonais-oeufs-jambon', 4, 'Faire sauter l''oignon et les carottes 4 minutes dans le reste de l''huile, puis ajouter le riz et le jambon et faire sauter 4 minutes : le riz doit être chaud et légèrement grillé.'),
  ('riz-saute-cantonais-oeufs-jambon', 5, 'Remettre les œufs, ajouter la sauce soja et l''huile de sésame, mélanger 1 minute et servir avec la ciboulette.'),
  ('soupe-nouilles-poulet-gingembre-soja', 1, 'Émincer les champignons et le chou, et couper le gingembre en fines lamelles.'),
  ('soupe-nouilles-poulet-gingembre-soja', 2, 'Porter de l''eau à ébullition dans un faitout avec le bouillon émietté, le gingembre et la sauce soja.'),
  ('soupe-nouilles-poulet-gingembre-soja', 3, 'Ajouter le poulet entier et le pocher 12 minutes à petits frémissements : il doit être cuit à cœur. Le sortir et l''effilocher.'),
  ('soupe-nouilles-poulet-gingembre-soja', 4, 'Pendant ce temps, cuire les œufs 6 minutes dans une casserole d''eau bouillante, les rafraîchir et les écaler.'),
  ('soupe-nouilles-poulet-gingembre-soja', 5, 'Ajouter les champignons, le chou et les nouilles au bouillon, et cuire 4 minutes : les nouilles doivent être tendres.'),
  ('soupe-nouilles-poulet-gingembre-soja', 6, 'Servir le bouillon avec le poulet effiloché, les œufs coupés en deux, l''huile de sésame et la coriandre.'),
  ('boeuf-saute-gingembre-brocoli-riz', 1, 'Cuire le riz dans une casserole d''eau bouillante selon le temps indiqué sur le paquet, puis l''égoutter.'),
  ('boeuf-saute-gingembre-brocoli-riz', 2, 'Couper le bœuf en fines lanières, détailler le brocoli en petits bouquets, râper le gingembre et hacher l''ail.'),
  ('boeuf-saute-gingembre-brocoli-riz', 3, 'Délayer la fécule dans la sauce soja, le miel et un peu d''eau.'),
  ('boeuf-saute-gingembre-brocoli-riz', 4, 'Saisir le bœuf 2 minutes dans l''huile, dans un wok à feu vif, puis le réserver : il doit rester rosé.'),
  ('boeuf-saute-gingembre-brocoli-riz', 5, 'Faire sauter le brocoli, l''ail et le gingembre 4 minutes avec un fond d''eau : le brocoli doit rester croquant.'),
  ('boeuf-saute-gingembre-brocoli-riz', 6, 'Remettre le bœuf, verser la sauce et mélanger 1 minute jusqu''à ce qu''elle nappe, puis servir avec le riz et le sésame.'),
  ('crevettes-sautees-ail-gingembre-nouilles', 1, 'Faire tremper les nouilles dans de l''eau bouillante hors du feu selon le temps du paquet, puis les égoutter.'),
  ('crevettes-sautees-ail-gingembre-nouilles', 2, 'Couper les carottes en fins bâtonnets, émincer le chou, hacher l''ail et râper le gingembre.'),
  ('crevettes-sautees-ail-gingembre-nouilles', 3, 'Faire sauter les crevettes avec l''ail et le gingembre 3 minutes dans l''huile, dans un wok à feu vif : elles doivent être roses. Les réserver.'),
  ('crevettes-sautees-ail-gingembre-nouilles', 4, 'Faire sauter les carottes et le chou 3 minutes, pousser les légumes sur le côté et brouiller les œufs 1 minute.'),
  ('crevettes-sautees-ail-gingembre-nouilles', 5, 'Ajouter les nouilles, les crevettes, la sauce soja et le jus de citron vert, mélanger 1 minute et servir avec la coriandre et les cacahuètes.'),
  ('porc-caramel-soja-riz-thai', 1, 'Couper le porc en cubes, émincer l''oignon, hacher l''ail et couper les carottes en rondelles.'),
  ('porc-caramel-soja-riz-thai', 2, 'Cuire le riz dans une casserole d''eau bouillante selon le temps indiqué sur le paquet, puis l''égoutter.'),
  ('porc-caramel-soja-riz-thai', 3, 'Faire fondre le sucre à sec dans une sauteuse à feu moyen, sans remuer, jusqu''à obtenir un caramel blond.'),
  ('porc-caramel-soja-riz-thai', 4, 'Hors du feu, verser la sauce soja et un fond d''eau (attention aux projections), puis remettre sur le feu et mélanger jusqu''à dissoudre le caramel.'),
  ('porc-caramel-soja-riz-thai', 5, 'Ajouter le porc, l''oignon, l''ail et les carottes, et laisser mijoter 20 minutes à couvert, puis 5 minutes à découvert : la sauce doit devenir sirupeuse et brillante.'),
  ('porc-caramel-soja-riz-thai', 6, 'Poivrer généreusement et servir avec le riz et la ciboulette.'),
  ('salade-nouilles-poulet-cacahuete-chou-rouge', 1, 'Faire tremper les nouilles dans de l''eau bouillante hors du feu selon le temps du paquet, les égoutter et les rincer à l''eau froide.'),
  ('salade-nouilles-poulet-cacahuete-chou-rouge', 2, 'Couper le poulet en lanières et le dorer 6 minutes dans l''huile, dans une poêle à feu moyen : il doit être cuit à cœur. Le laisser tiédir.'),
  ('salade-nouilles-poulet-cacahuete-chou-rouge', 3, 'Émincer finement le chou rouge et râper les carottes et le gingembre.'),
  ('salade-nouilles-poulet-cacahuete-chou-rouge', 4, 'Fouetter le beurre de cacahuète avec la sauce soja, le jus de citron vert, le gingembre et un peu d''eau jusqu''à obtenir une sauce nappante.'),
  ('salade-nouilles-poulet-cacahuete-chou-rouge', 5, 'Mélanger les nouilles, le poulet, les légumes et la sauce, puis servir avec l''huile de sésame et la coriandre.'),
  ('croque-vege-tomates-sechees-epinards', 1, 'Tartiner les tranches de pain de mie de fromage frais et couper les tomates séchées en lanières.'),
  ('croque-vege-tomates-sechees-epinards', 2, 'Garnir la moitié des tranches de tomates séchées, d''épinards et d''emmental râpé, poivrer, puis refermer avec les autres tranches.'),
  ('croque-vege-tomates-sechees-epinards', 3, 'Beurrer l''extérieur des croques et les cuire 4 à 5 minutes de chaque côté dans une poêle à feu moyen, en pressant : ils doivent être dorés et le fromage fondu.'),
  ('croque-vege-tomates-sechees-epinards', 4, 'Couper en deux et servir aussitôt avec la mâche.'),
  ('omelette-tomates-sechees-feta-ciboulette', 1, 'Couper les tomates séchées en lanières, émietter la feta et ciseler la ciboulette.'),
  ('omelette-tomates-sechees-feta-ciboulette', 2, 'Battre les œufs avec du poivre et la ciboulette.'),
  ('omelette-tomates-sechees-feta-ciboulette', 3, 'Verser les œufs dans l''huile chaude, dans une poêle à feu moyen, et ramener les bords vers le centre pendant 2 minutes.'),
  ('omelette-tomates-sechees-feta-ciboulette', 4, 'Parsemer de tomates séchées et de feta, et cuire encore 2 minutes : le dessus doit rester légèrement baveux.'),
  ('omelette-tomates-sechees-feta-ciboulette', 5, 'Plier l''omelette en deux et servir avec le pain grillé et la mâche.'),
  ('wraps-poulet-tomates-sechees-fromage-frais', 1, 'Couper le poulet en fines lanières et les tomates séchées en morceaux.'),
  ('wraps-poulet-tomates-sechees-fromage-frais', 2, 'Dorer le poulet 6 minutes dans l''huile avec le paprika, dans une poêle à feu moyen-vif : il doit être cuit à cœur.'),
  ('wraps-poulet-tomates-sechees-fromage-frais', 3, 'Tartiner les tortillas de fromage frais et répartir le poulet, les tomates séchées et la mâche.'),
  ('wraps-poulet-tomates-sechees-fromage-frais', 4, 'Rouler les tortillas bien serrées en rabattant les côtés, puis les couper en deux.'),
  ('quesadillas-haricots-rouges-tomates-sechees', 1, 'Égoutter et rincer les haricots, puis les écraser grossièrement à la fourchette avec le cumin.'),
  ('quesadillas-haricots-rouges-tomates-sechees', 2, 'Émincer finement l''oignon rouge, couper les tomates séchées en morceaux et râper le cheddar.'),
  ('quesadillas-haricots-rouges-tomates-sechees', 3, 'Étaler les haricots sur deux tortillas, ajouter l''oignon, les tomates séchées et le cheddar, puis couvrir des deux autres tortillas.'),
  ('quesadillas-haricots-rouges-tomates-sechees', 4, 'Cuire chaque quesadilla 2 à 3 minutes de chaque côté dans une poêle à sec à feu moyen : elle doit être dorée et le fromage fondu.'),
  ('quesadillas-haricots-rouges-tomates-sechees', 5, 'Couper en parts et servir avec la mâche arrosée de jus de citron vert.'),
  ('tartines-ricotta-tomates-sechees-jambon-cru', 1, 'Griller les tranches de pain 3 minutes au grille-pain ou sous le gril du four : elles doivent être dorées et croustillantes.'),
  ('tartines-ricotta-tomates-sechees-jambon-cru', 2, 'Mélanger la ricotta avec le jus de citron et du poivre.'),
  ('tartines-ricotta-tomates-sechees-jambon-cru', 3, 'Couper les tomates séchées en lanières.'),
  ('tartines-ricotta-tomates-sechees-jambon-cru', 4, 'Tartiner le pain de ricotta, ajouter les tomates séchées, le jambon cru et la mâche, puis arroser d''un filet d''huile.'),
  ('gnocchis-poeles-tomates-sechees-mozzarella', 1, 'Couper les tomates séchées en lanières, hacher l''ail et couper la mozzarella en dés.'),
  ('gnocchis-poeles-tomates-sechees-mozzarella', 2, 'Dorer les gnocchis 8 minutes dans l''huile, dans une grande poêle à feu moyen, en remuant souvent : ils doivent être croustillants à l''extérieur.'),
  ('gnocchis-poeles-tomates-sechees-mozzarella', 3, 'Ajouter l''ail, les tomates séchées et les épinards, et mélanger 2 minutes jusqu''à ce que les épinards tombent.'),
  ('gnocchis-poeles-tomates-sechees-mozzarella', 4, 'Hors du feu, ajouter la mozzarella et le parmesan râpé, poivrer, couvrir 1 minute pour faire fondre et servir avec le basilic.')
) as v(recipe, pos, instruction)
join public.recipes r on r.slug = v.recipe;

-- Garde-fou : une jointure silencieusement vide (slug introuvable) fait échouer la migration.
do $$
begin
  if (select count(*) from public.recipe_ingredients ri join public.recipes r on r.id = ri.recipe_id
      where r.slug in ('curry-rouge-poulet-butternut-coco', 'tofu-curry-rouge-epinards-coco', 'poulet-satay-cacahuete-carottes-riz', 'riz-saute-cantonais-oeufs-jambon', 'soupe-nouilles-poulet-gingembre-soja', 'boeuf-saute-gingembre-brocoli-riz', 'crevettes-sautees-ail-gingembre-nouilles', 'porc-caramel-soja-riz-thai', 'salade-nouilles-poulet-cacahuete-chou-rouge', 'croque-vege-tomates-sechees-epinards', 'omelette-tomates-sechees-feta-ciboulette', 'wraps-poulet-tomates-sechees-fromage-frais', 'quesadillas-haricots-rouges-tomates-sechees', 'tartines-ricotta-tomates-sechees-jambon-cru', 'gnocchis-poeles-tomates-sechees-mozzarella')) <> 140 then
    raise exception 'Lignes d''ingrédients manquantes dans le dix-neuvième lot de recettes.';
  end if;
end;
$$;
